public class ShopTypes {
    public static void main(String[] args) {
        int cartons = 7;                    // whole numbers
        double sugarKg = 2.5;               // numbers with a point
        char grade = 'A';                   // one letter, single quotes
        boolean isOpen = true;              // only true or false
        String item = "Noodles";            // text, double quotes
        final int MAX_SHELF = 50;           // final = can never change

        int pieces = cartons * 40;          // 40 packs in a carton
        double perDay = pieces / 3.0;       // 3.0 keeps the decimals
        int roughPerDay = (int) perDay;     // casting chops off the decimals

        System.out.println(item + " packs: " + pieces);
        System.out.println("Per day: " + perDay + " (rough: " + roughPerDay + ")");
        System.out.println("Sugar: " + sugarKg + "kg, shop grade " + grade);
        System.out.println("Open? " + isOpen + " | Shelf full? " + (pieces > MAX_SHELF));
    }
}

public class Restock {
    public static void main(String[] args) {
        String[] items = {"Milk", "Sugar", "Noodles", "Bread"};
        int[] stock = {12, 3, 0, 40};

        for (int i = 0; i < items.length; i++) {
            if (stock[i] == 0) {
                System.out.println(items[i] + ": FINISHED - buy today!");
            } else if (stock[i] < 5) {
                System.out.println(items[i] + ": LOW (" + stock[i] + " left)");
            } else {
                System.out.println(items[i] + ": OKAY (" + stock[i] + ")");
            }
        }

        int day = 1, bread = 20;
        while (bread > 0) {
            bread -= 6;
            System.out.println("Day " + day + ", bread left: " + Math.max(bread, 0));
            day++;
        }
    }
}

class Product {
    String name;
    int price;
    int qty;
    Product(String name, int price, int qty) {
        this.name = name; this.price = price; this.qty = qty;
    }
    int value() { return price * qty; }
}
class Drink extends Product {
    boolean chilled;
    Drink(String name, int price, int qty, boolean chilled) {
        super(name, price, qty);       // let Product fill the shared details
        this.chilled = chilled;
    }
}
