interface Discountable {
    int discountedPrice(int percent);
}
interface Perishable {
    boolean expiresSoon(int daysLeft);
}
class Bread implements Discountable, Perishable {
    int price = 1000;
    public int discountedPrice(int percent) { return price - price * percent / 100; }
    public boolean expiresSoon(int daysLeft) { return daysLeft <= 1; }
}
class Soap implements Discountable {
    int price = 600;
    public int discountedPrice(int percent) { return price - price * percent / 100; }
}
public class Promo {
    public static void main(String[] args) {
        Bread bread = new Bread();
        Discountable[] promo = { bread, new Soap() };
        for (Discountable d : promo) {
            System.out.println(d.getClass().getSimpleName() + " promo price: N" + d.discountedPrice(20));
        }
        if (bread.expiresSoon(1)) System.out.println("Sell the bread first - it expires tomorrow!");
    }
}

public class SafeQty {
    public static void main(String[] args) {
        String[] typed = {"12", "five", "0", "8"};     // what the shop boy typed
        int total = 0;
        for (String t : typed) {
            try {
                int qty = Integer.parseInt(t);
                int perItem = 2400 / qty;               // share N2,400 across the items
                total += qty;
                System.out.println(qty + " items, N" + perItem + " each");
            } catch (NumberFormatException e) {
                System.out.println("'" + t + "' is not a number - please type digits");
            } catch (ArithmeticException e) {
                System.out.println("Cannot share by zero items!");
            }
        }
        System.out.println("Total items recorded: " + total);
    }
}

class OutOfStockException extends Exception {
    OutOfStockException(String msg) { super(msg); }
}
public class Sell {
    static int milk = 5;
    static void sell(int qty) throws OutOfStockException {
        if (qty > milk) {
            throw new OutOfStockException("Only " + milk + " tins left, you asked for " + qty);
        }
        milk -= qty;
        System.out.println("Sold " + qty + ". Left: " + milk);
    }
    public static void main(String[] args) {
        int[] orders = {2, 4, 3};
        for (int q : orders) {
            try {
                sell(q);
            } catch (OutOfStockException e) {
                System.out.println("Sorry o: " + e.getMessage());
            } finally {
                System.out.println("-- order written in the daily book --");
            }
        }
    }
}

import java.io.FileWriter;
import java.io.IOException;
import java.io.PrintWriter;

public class SaveStock {
    public static void main(String[] args) {
        String[] items = {"Rice", "Beans", "Garri", "Sugar"};
        int[] qty = {30, 12, 25, 8};
        int[] price = {1200, 1500, 800, 1100};

        try (PrintWriter out = new PrintWriter(new FileWriter("stock.txt"))) {
            for (int i = 0; i < items.length; i++) {
                out.println(items[i] + "," + qty[i] + "," + price[i]);
            }
            System.out.println("Saved " + items.length + " items to stock.txt");
        } catch (IOException e) {
            System.out.println("Could not save: " + e.getMessage());
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class ReadStock {
    public static void main(String[] args) {
        int total = 0;
        try (BufferedReader in = new BufferedReader(new FileReader("stock.txt"))) {
            String line;
            while ((line = in.readLine()) != null) {
                String[] parts = line.split(",");
                int qty = Integer.parseInt(parts[1].trim());
                int price = Integer.parseInt(parts[2].trim());
                total += qty * price;
                if (qty < 10) System.out.println("Restock soon: " + parts[0]);
            }
            System.out.println("Total stock value: N" + total);
        } catch (IOException e) {
            System.out.println("Could not read stock.txt: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.out.println("A line in the file is broken: " + e.getMessage());
        }
    }
}
